function boardPanel(title,body,extra='',cls=''){return `<section class="board-panel ${cls}"><div class="board-panel-head"><h2><i></i>${title}</h2>${extra}</div>${body}</section>`}
function boardTrend(){let values=[260,318,372,386,294,362,408,320,286,242],max=500,base=152;let points=values.map((v,i)=>`${58+i*54},${base-v/max*128}`).join(' ');return `<svg class="board-trend" viewBox="0 0 610 184" preserveAspectRatio="none" role="img" aria-label="每小时产量，合计3248台，小时计划420台"><defs><linearGradient id="barFill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#4edbcc"/><stop offset="1" stop-color="#158a9a" stop-opacity=".35"/></linearGradient><linearGradient id="areaFill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#37ccca" stop-opacity=".22"/><stop offset="1" stop-color="#37ccca" stop-opacity="0"/></linearGradient></defs>${[0,200,400].map(v=>`<line x1="33" y1="${base-v/max*128}" x2="598" y2="${base-v/max*128}" stroke="#234054" stroke-dasharray="3 5"/><text x="24" y="${base-v/max*128+4}" text-anchor="end" fill="#7d99ad" font-size="10">${v}</text>`).join('')}<line x1="33" y1="${base-420/max*128}" x2="598" y2="${base-420/max*128}" stroke="#e1b66b" stroke-dasharray="6 5" opacity=".8"/><polygon points="58,152 ${points} 544,152" fill="url(#areaFill)"/>${values.map((v,i)=>`<rect x="${45+i*54}" y="${base-v/max*128}" width="26" height="${v/max*128}" rx="4" fill="url(#barFill)"/><text x="${58+i*54}" y="${base-v/max*128-7}" text-anchor="middle" fill="#c5e6ec" font-size="10">${v}</text><text x="${58+i*54}" y="174" text-anchor="middle" fill="#8aabbd" font-size="10">${8+i}:00</text>`).join('')}</svg>`}
function boardQuality(){return `<div class="quality-ring"><svg viewBox="0 0 180 180" role="img" aria-label="一次合格率98.7%"><circle cx="90" cy="90" r="69" fill="none" stroke="#203b50" stroke-width="11"/><circle cx="90" cy="90" r="69" fill="none" stroke="#47ddbd" stroke-width="11" stroke-dasharray="428 434" transform="rotate(-90 90 90)" stroke-linecap="round"/><circle cx="90" cy="90" r="55" fill="none" stroke="#29445a" stroke-width="1" stroke-dasharray="2 6"/><text x="90" y="87" text-anchor="middle" fill="#edfaff" font-size="30" font-weight="700">98.7<tspan font-size="14">%</tspan></text><text x="90" y="111" text-anchor="middle" fill="#83a6b8" font-size="12">一次合格率</text></svg><div class="quality-totals"><span><i class="qdot pass"></i>合格 <b>3,248</b></span><span><i class="qdot fail"></i>不合格 <b>43</b></span></div></div>`}
function screen(){let rows=[{line:'A01 装配线',model:'P20 / 20W 快充',order:'MO-20261015-001',done:1486,plan:2000,state:'运行中'},{line:'A02 装配线',model:'P30 / 30W 快充',order:'MO-20261015-002',done:768,plan:1200,state:'运行中'},{line:'B01 包装线',model:'P20 / 包装入库',order:'MO-20261015-003',done:994,plan:1000,state:'即将完成'}];let metrics=[['今日完成产量','3,248','台','计划 4,200 台','◈'],['计划达成率','77.3','%','剩余目标 952 台','↗'],['一次合格率','98.7','%','检验 3,291 台 / 不合格 43 台','✓'],['在线工位','21','/ 24','设备在线 16 / 18 台','▦']];let recent=typeof instrumentResults==='function'?instrumentResults().slice(0,4):[];return `<div class="production-board"><header class="board-header"><div class="board-brand"><span>ϟ</span><div>POWER MES<small>制造执行系统 · A区车间</small></div></div><div class="board-title"><div>充电宝生产数据中心</div><small>PRODUCTION OPERATIONS CENTER</small></div><div class="board-tools"><div><b id="boardClock">${new Date().toLocaleTimeString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'})}</b><small>${new Date().toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'})}　日班</small></div><button onclick="boardFullscreen()" aria-label="切换全屏" title="切换全屏">⛶</button><button onclick="setMode('pc')" title="返回管理后台">返回</button></div></header><div class="board-metrics">${metrics.map((m,i)=>`<section class="board-metric"><div class="metric-caption">${m[0]}<span>${m[4]}</span></div><div class="metric-value tone-${i}">${m[1]}<small>${m[2]}</small></div><div class="metric-note">${m[3]}</div><div class="metric-edge"></div></section>`).join('')}</div><div class="board-middle">${boardPanel('小时产量趋势',boardTrend(),'<span class="board-legend"><i></i>实际产量 <em></em>小时计划 420</span>','trend-panel')}${boardPanel('质量表现',boardQuality(),'<span class="board-subtle">今日累计</span>')}${boardPanel('现场异常',`<div class="board-alert"><span class="alert-icon">!</span><div><h3>ATE-003 设备离线</h3><p>A02 测试工位 · 心跳中断</p><small>设备组处理中</small></div><b>08<span>分钟</span></b></div><div class="board-alert amber"><span class="alert-icon">!</span><div><h3>3 台产品等待返修</h3><p>USB-C 输出电流偏低</p><small>质量组已接收</small></div><b>03<span>台</span></b></div><div class="board-alert-footer"><span class="qdot pass"></span>其他工位运行正常</div>`, '<span class="board-count">2 项待处理</span>')}</div><div class="board-lower">${boardPanel('产线与工单进度',`<div class="board-lines"><div class="board-line-labels"><span>产线 / 产品</span><span>生产工单</span><span>完成 / 计划</span><span>完成进度</span><span>状态</span></div>${rows.map(r=>`<div class="board-line"><div><b>${r.line}</b><small>${r.model}</small></div><span class="board-order">${r.order}</span><div><strong>${r.done.toLocaleString()}</strong><small> / ${r.plan.toLocaleString()} 台</small></div><div><div class="board-progress"><i style="width:${r.done/r.plan*100}%"></i></div><b class="line-percent">${(r.done/r.plan*100).toFixed(1)}%</b></div><span class="board-status">${r.state}</span></div>`).join('')}</div>`, '<span class="board-subtle">3 条产线 · 当前日班</span>','board-line-panel')}${boardPanel('最新仪器测试结果',recent.length?`<div class="board-results">${recent.map(t=>`<div><span><b>${escapeHtml(t.main)}</b><small>${escapeHtml(t.time)} · ${escapeHtml(t.device||'ATE-001')}</small></span><strong class="${t.result==='PASS'?'result-pass':'result-fail'}">${t.result}</strong></div>`).join('')}</div>`:`<div class="board-wait"><span class="wait-radar"></span><h3>等待测试数据上传</h3><p>仪器结果接收后自动显示</p></div>`,'<span class="board-subtle">自动接收</span>')}</div><section class="board-flow"><div class="flow-label"><h2>工序流转</h2><small>PROCESS FLOW</small></div>${steps.map((s,i)=>`<div class="flow-step"><span class="flow-no">0${i+1}</span><div><b>${s}</b><small>${['扫描主码建立记录','主码与电芯码关联','PASS / FAIL 自动上传','主码与成品 SN 关联','SN 与包装码关联'][i]}</small></div><span class="flow-arrow">›</span></div>`).join('')}</section><footer class="board-footer"><span><i class="qdot pass"></i>生产监控概览</span><span>界面演示 · 汇总指标为模拟数据，测试列表来自本机演示记录</span><span>POWER MES · V1.0</span></footer></div>`}
function boardFullscreen(){if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>toast('当前环境不支持全屏，请使用浏览器全屏功能'))}
setInterval(()=>{let el=document.getElementById('boardClock');if(el)el.textContent=new Date().toLocaleTimeString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'})},1000);
